const WORK_START = 8;
const WORK_END = 20;
const SLOT_MIN = 60;
const ZONE = $env.CHRONOS_TIMEZONE || 'America/Sao_Paulo'; // configurável no .env (CHRONOS_TIMEZONE)

const input = $('Entrada').first().json;
const task = $('Obter tarefa').first().json;
let dayTasks = [];
try { dayTasks = $input.first().json.results || []; } catch (e) { dayTasks = []; }

const day = DateTime.fromISO(String(input.date), { zone: ZONE });
const now = DateTime.now().setZone(ZONE);

const busy = [];
for (const t of dayTasks) {
  if (!t || t.id === task.id || !t.due || !t.due.date || !String(t.due.date).includes('T')) continue;
  const s = DateTime.fromISO(t.due.date, { zone: ZONE });
  const dur = t.duration && t.duration.unit === 'minute' && t.duration.amount > 0 ? t.duration.amount : SLOT_MIN;
  busy.push({ s, e: s.plus({ minutes: dur }), content: t.content });
}
const isFree = (s, e) => busy.every(b => e <= b.s || s >= b.e);

let earliest = day.startOf('day');
if (day.hasSame(now, 'day')) earliest = now.startOf('hour').plus({ hours: 1 });

const candidates = [];
const hasTime = task.due && task.due.date && String(task.due.date).includes('T');
let originalLabel = null;
if (hasTime) {
  const orig = DateTime.fromISO(task.due.date, { zone: ZONE });
  originalLabel = orig.toFormat('HH:mm');
  candidates.push({ dt: day.set({ hour: orig.hour, minute: orig.minute, second: 0, millisecond: 0 }), reason: 'horário original mantido' });
}
for (let h = WORK_START; h < WORK_END; h++) {
  candidates.push({ dt: day.set({ hour: h, minute: 0, second: 0, millisecond: 0 }), reason: 'próximo horário livre' });
}

let chosen = null;
for (const c of candidates) {
  if (c.dt < earliest) continue;
  if (!isFree(c.dt, c.dt.plus({ minutes: SLOT_MIN }))) continue;
  chosen = c; break;
}

return [{ json: {
  task_id: task.id,
  content: task.content,
  date: String(input.date),
  found: !!chosen,
  due_datetime: chosen ? chosen.dt.toISO() : null,
  time: chosen ? chosen.dt.toFormat('HH:mm') : null,
  reason: chosen ? chosen.reason : 'sem horário livre entre ' + WORK_START + 'h e ' + WORK_END + 'h; só a data foi definida',
  original_time: originalLabel,
  busy: busy.map(b => b.s.toFormat('HH:mm') + '-' + b.e.toFormat('HH:mm') + ' ' + b.content),
} }];

const input = $('Entrada').first().json;
const plan = $('Escolher horário livre').first().json;
let saved = null;
try { saved = $('Todoist: gravar horário').first().json; } catch (e) { saved = null; }
if (!saved) { try { saved = $('Todoist: gravar só a data').first().json; } catch (e) { saved = null; } }
const failed = !saved || !!saved.error;
return [{ json: {
  ok: !failed,
  task_id: plan.task_id,
  content: plan.content,
  date: plan.date,
  time: (!failed && plan.found) ? plan.time : null,
  reason: failed ? ('Todoist: ' + ((saved && saved.error && saved.error.message) || 'erro')) : plan.reason,
  original_time: plan.original_time,
  due: (!failed && saved.due) ? saved.due : null,
  echo: input.echo || {},
} }];
